example.code:
using Devinno.UI.App;
using Devinno.UI.OpenTK;
using Devinno.UI.Styling;

var app = new DvApp { Theme = DvTheme.Dark };
app.Pages.Add(new MainPage());   // DvPage 를 상속한 페이지(마크업 + 뷰모델 역할)
using var window = new ViewWindow(app, 1280, 800, "My HMI") { Gpu = true };

// 다른 스레드에서 값을 바꾸고 화면 갱신 요청
using var poll = new System.Threading.Timer(_ => app.Invalidate(), null, 1000, 1000);

window.Run();   // 창이 닫힐 때까지 돌아오지 않음

using var window = new ViewWindow(app, 1280, 800, "HMI");
window.HandlerError += (_, e) => Log.Error(e.Exception, $"{e.Kind} {e.Member} ({e.Tag})");
window.Run();
